def advice(current,side=None):
    current=date.fromisoformat(current) if isinstance(current,str) else current
    if current<START: return 'До начала войны 28.06.2057. Канон не назначает наступлений'
    if current>END: return 'После официального окончания 12.11.2060. Альтернативная история разрешена'
    row=next(p for p in PHASES if current<=date.fromisoformat(p[0]))
    _,phase,initiative,attack,defence=row
    text=f'{current:%d.%m.%Y}\nФаза: {phase}\nИнициатива: {initiative}\nОперации и направления: {attack}\nОборона: {defence}'
    if side:
        text+='\nСовет выбранной стороне: '+('Кефирстан' if side=='kefir' else 'Йогуртстан')+' — используйте соответствующие направления выше'
    return text+'\nЭто подсказка по хронике. Приказы и выбор точек на карте остаются за вами'
